#include <cstddef>
#include <cstdint>
#include <iostream>
#include <string>
#include <vector>
constexpr std::uint32_t mod=998244353;
std::uint32_t add(std::uint32_t a,std::uint32_t b){auto s=a+b;return s>=mod?s-mod:s;}
std::uint32_t sub(std::uint32_t a,std::uint32_t b){return a>=b?a-b:a+mod-b;}
int main(int argc,char**argv){if(argc!=2)return 1;std::ios::sync_with_stdio(false);std::cin.tie(nullptr);const bool gcd=std::string(argv[1])=="gcd_convolution";std::size_t n;if(!(std::cin>>n))return 1;std::vector<std::uint32_t>a(n+1),b(n+1),f(n+1),g(n+1),c(n+1);for(std::size_t i=1;i<=n;++i)std::cin>>a[i];for(std::size_t i=1;i<=n;++i)std::cin>>b[i];
 for(std::size_t d=1;d<=n;++d)for(std::size_t k=d;k<=n;k+=d){if(gcd){f[d]=add(f[d],a[k]);g[d]=add(g[d],b[k]);}else{f[k]=add(f[k],a[d]);g[k]=add(g[k],b[d]);}}
 for(std::size_t k=1;k<=n;++k)c[k]=static_cast<std::uint32_t>(std::uint64_t(f[k])*g[k]%mod);
 if(gcd){for(std::size_t d=n;d;--d)for(std::size_t k=d+d;k<=n;k+=d)c[d]=sub(c[d],c[k]);}else{for(std::size_t d=1;d<=n;++d)for(std::size_t k=d+d;k<=n;k+=d)c[k]=sub(c[k],c[d]);}
 for(std::size_t k=1;k<=n;++k)std::cout<<c[k]<<(k==n?'\n':' ');
}

